import xml.etree.ElementTree as ET
import glob, os

ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
path = glob.glob('unpacked/word/document.xml')
if not path:
    print("NO document.xml found")
    raise SystemExit(1)

tree = ET.parse(path[0])
root = tree.getroot()
body = root.find('w:body', ns)

for i, p in enumerate(body.findall('w:p', ns)):
    ppr = p.find('w:pPr', ns)
    style = pstyle = outline = None
    texts = []
    if ppr is not None:
        ps = ppr.find('w:pStyle', ns)
        if ps is not None:
            style = ps.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}val')
        ol = ppr.find('w:outlineLvl', ns)
        if ol is not None:
            outline = ol.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}val')
    for r in p.findall('w:r', ns):
        for t in r.findall('w:t', ns):
            texts.append(t.text or '')
        for t in r.findall('w:delText', ns):
            texts.append('[DEL:' + (t.text or '') + ']')
    txt = ''.join(texts)
    print(f"[{i}] style={style} outline={outline} text={txt[:120]!r}")

import re

path = 'unpacked/word/document.xml'
with open(path, 'r', encoding='utf-8') as f:
    xml = f.read()

para_re = re.compile(r'<w:p\b.*?</w:p>', re.DOTALL)
t_re = re.compile(r'<w:t[^>]*>(.*?)</w:t>', re.DOTALL)
rpr_re = re.compile(r'(<w:rPr>)(.*?)(</w:rPr>)', re.DOTALL)

def para_text(p):
    return ''.join(t_re.findall(p))

headlines = [p for p in para_re.findall(xml)
             if (lambda t: t and not any(c.islower() for c in t)
                 and any(c.isupper() for c in t))(para_text(p).strip())]

print('headlines found: %d' % len(headlines))
for p in headlines:
    print(repr(para_text(p).strip()))

def underline_para(p):
    return rpr_re.sub(lambda m: m.group(1) + m.group(2)
                      + '<w:u w:val="single"/>' + m.group(3), p)

for p in headlines:
    xml = xml.replace(p, underline_para(p))

with open(path, 'w', encoding='utf-8') as f:
    f.write(xml)

print('done: %d headline paragraphs underlined' % len(headlines))

